'use strict';
const $=id=>document.getElementById(id), PARTS=['항공구','항공등','애자련','부지'];
let db, records=[], line='내 선로', tower=1, part='항공등', photos=[], processing=0, saving=false, current='listView', previous='listView', dirty=false;
const statuses=p=>p==='항공등'?['미확인','정상 점멸','정상 점등','소등 / 고장','미설치']:p==='부지'?['미확인','양호','정비 필요']:['미확인','양호','이상 있음','미설치'];
const stamp=d=>new Date(d).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
function req(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function transaction(store,mode,action){return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode);action(tx);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('저장이 취소되었습니다.'));});}
async function reload(){records=await req(db.transaction('records').objectStore('records').getAll());const m=await req(db.transaction('meta').objectStore('meta').get('line'));line=m?.value||'내 선로';render();}
function show(view){current=view;['listView','towerView','settingsView'].forEach(id=>$(id).hidden=id!==view);render();window.scrollTo(0,0);}
function latest(p){return records.filter(r=>r.tower===tower&&r.part===p).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0];}
function bad(s){return ['소등 / 고장','이상 있음','정비 필요'].includes(s);}
function render(){
 $('lineTitle').textContent=line;$('towerLine').textContent=line;$('towerTitle').textContent=tower+'호 철탑';$('lineInput').value=line;
 $('recorded').textContent=new Set(records.map(r=>r.tower)).size;
 const fragment=document.createDocumentFragment();for(let n=1;n<=100;n++){if($('search').value&&!String(n).includes($('search').value.trim()))continue;const r=records.filter(r=>r.tower===n);const issue=PARTS.some(p=>bad(r.filter(x=>x.part===p).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0]?.status));const b=document.createElement('button');b.className='towercell'+(r.length?' done':'')+(issue?' issue':'');const name=document.createElement('span');name.textContent=n+'호';const state=document.createElement('small');state.textContent=issue?'! 이상 기록':r.length?'● 기록 있음':'○ 기록 없음';b.append(name,state);b.onclick=()=>{tower=n;show('towerView');};fragment.append(b);}$('towerGrid').replaceChildren(fragment);if(!fragment.childNodes.length&&!$('towerGrid').childNodes.length)$('towerGrid').textContent='해당 호수가 없습니다.';
 const l=latest('항공등'), blinking=l?.status==='정상 점멸', color=l?.status.startsWith('정상')?'#d96044':'#87958f';$('lampDot').style.background=color;$('lampMark').setAttribute('fill',color);['lampDot','lampMark'].forEach(id=>$(id).classList.toggle('blink',blinking));$('lampSummary').textContent='항공등: '+(l?l.status+' · '+stamp(l.createdAt)+' 확인':'미확인 · 점검 기록 없음');
 $('partList').replaceChildren();PARTS.forEach(p=>{const r=latest(p),b=document.createElement('button');b.className='partrow';const a=document.createElement('span');a.textContent=p;const small=document.createElement('small');small.textContent=r?stamp(r.createdAt):'아직 기록이 없습니다';a.append(small);const value=document.createElement('span');value.className='value';value.textContent=(r?.status||'미확인')+' ›';b.append(a,value);b.onclick=()=>openEditor(p);$('partList').append(b);});
}
function openEditor(p){part=p;photos=[];dirty=false;$('recordForm').reset();$('editorTower').textContent=line+' / '+tower+'호';$('partTitle').textContent=p;$('statusInput').replaceChildren(...statuses(p).map(s=>new Option(s,s)));$('landOptions').hidden=p!=='부지';renderPhotos();renderHistory();$('editor').showModal();}
function renderHistory(){const items=records.filter(r=>r.tower===tower&&r.part===part).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('history').replaceChildren();if(!items.length){$('history').textContent='저장된 기록이 없습니다.';return;}items.forEach(r=>{const div=document.createElement('div');div.className='historyitem';const title=document.createElement('strong');title.textContent=r.status+(r.land.length?' · '+r.land.join(', '):'');const date=document.createElement('small');date.textContent=stamp(r.createdAt);const p=document.createElement('p');p.textContent=r.note;const pics=document.createElement('div');pics.className='historyphotos';r.photos.forEach((src,i)=>{const img=document.createElement('img');img.src=src;img.alt=r.part+' 현장 사진 '+(i+1);img.loading='lazy';pics.append(img);});div.append(title,document.createElement('br'),date,p,pics);$('history').append(div);});}
function renderPhotos(){$('photoPreview').replaceChildren();photos.forEach((src,i)=>{const box=document.createElement('div');box.className='photoitem';const img=document.createElement('img');img.src=src;img.alt='첨부 사진 '+(i+1);const b=document.createElement('button');b.type='button';b.textContent='삭제';b.onclick=()=>{photos.splice(i,1);dirty=true;renderPhotos();};box.append(img,b);$('photoPreview').append(box);});}
function compress(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(new Error('이미지 파일을 선택해주세요.'));const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{try{const scale=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.8));}catch(e){reject(e);}finally{URL.revokeObjectURL(url);}};im.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('사진을 읽지 못했습니다. JPEG 사진으로 다시 선택해주세요.'));};im.src=url;});}
async function addPhotos(event){if(processing)return;processing++;$('saveRecord').disabled=true;try{const files=[...event.target.files];if(files.length+photos.length>8)throw new Error('한 기록에는 사진을 최대 8장 넣을 수 있습니다.');for(const file of files){photos.push(await compress(file));dirty=true;}renderPhotos();}catch(e){renderPhotos();toast(e.message);}finally{event.target.value='';processing--;$('saveRecord').disabled=false;}}
function closeEditor(){if(processing||saving){toast('사진 처리 또는 저장이 끝날 때까지 기다려주세요.');return;}if(dirty&&!confirm('저장하지 않은 입력을 닫을까요?'))return;$('editor').close();}
$('camera').onchange=addPhotos;$('gallery').onchange=addPhotos;$('recordForm').oninput=()=>dirty=true;$('closeEditor').onclick=closeEditor;$('editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});
$('recordForm').onsubmit=async e=>{e.preventDefault();if(processing||saving)return;saving=true;$('saveRecord').disabled=true;const record={id:crypto.randomUUID(),tower,part,status:$('statusInput').value,note:$('noteInput').value.trim(),land:part==='부지'?[...$('landOptions').querySelectorAll('input:checked')].map(x=>x.value):[],photos:[...photos],createdAt:new Date().toISOString()};try{await transaction('records','readwrite',tx=>tx.objectStore('records').add(record));records.push(record);dirty=false;$('editor').close();render();toast(tower+'호 '+part+' 기록을 저장했습니다.');navigator.storage?.persist?.().catch(()=>{});}catch(e){toast('저장하지 못했습니다. 저장 공간을 확인한 후 다시 시도해주세요.');}finally{saving=false;$('saveRecord').disabled=false;}};
$('back').onclick=()=>show('listView');$('search').oninput=render;document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>openEditor(b.dataset.part));$('settingsBtn').onclick=()=>{previous=current==='settingsView'?previous:current;show('settingsView');};$('settingsBack').onclick=()=>show(previous);
$('saveLine').onclick=async()=>{const name=$('lineInput').value.trim();if(!name)return toast('선로 이름을 입력해주세요.');try{await transaction('meta','readwrite',tx=>tx.objectStore('meta').put({key:'line',value:name}));line=name;render();toast('선로 이름을 저장했습니다.');}catch(e){toast('선로 이름을 저장하지 못했습니다.');}};
$('exportBtn').onclick=()=>{const data={format:'tower-ledger',version:1,exportedAt:new Date().toISOString(),line,records};const blob=new Blob([JSON.stringify(data)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='철탑대장-백업-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('backupStatus').textContent='백업 파일 다운로드를 요청했습니다. 파일 앱에서 저장 여부를 확인하세요.';};
function validate(data){if(data?.format!=='tower-ledger'||data.version!==1||typeof data.line!=='string'||!data.line.trim()||data.line.length>60||!Array.isArray(data.records))throw new Error('지원하는 대장 백업 파일이 아닙니다.');const ids=new Set();for(const r of data.records){if(!r||typeof r.id!=='string'||r.id.length>100||ids.has(r.id)||!Number.isInteger(r.tower)||r.tower<1||r.tower>100||!PARTS.includes(r.part)||!statuses(r.part).includes(r.status)||typeof r.note!=='string'||r.note.length>3000||!Array.isArray(r.land)||!r.land.every(x=>['도심지','칡밭','산지','농경지','기타'].includes(x))||!Array.isArray(r.photos)||r.photos.length>8||!r.photos.every(x=>typeof x==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(x))||typeof r.createdAt!=='string'||!Number.isFinite(Date.parse(r.createdAt)))throw new Error('백업 기록의 형식이 올바르지 않습니다.');ids.add(r.id);}return data;}
$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=validate(JSON.parse(await file.text()));if(records.length&&data.line!==line)throw new Error('현재 선로와 이름이 다른 백업입니다. 잘못 합쳐지지 않도록 불러오기를 중단했습니다.');const existing=new Set(records.map(r=>r.id)),add=data.records.filter(r=>!existing.has(r.id));if(!confirm(data.line+'의 기록 '+add.length+'개를 추가할까요? 기존 기록은 유지됩니다.'))return;await transaction(['records','meta'],'readwrite',tx=>{add.forEach(r=>tx.objectStore('records').add(r));tx.objectStore('meta').put({key:'line',value:data.line});});await reload();toast(add.length+'개 기록을 불러왔습니다.');}catch(err){toast('불러오기 실패: '+err.message);}finally{e.target.value='';}};
window.addEventListener('beforeunload',e=>{if(dirty&&$('editor').open){e.preventDefault();e.returnValue='';}});
(async()=>{try{const open=indexedDB.open('tower-ledger-v1',1);open.onupgradeneeded=()=>{open.result.createObjectStore('records',{keyPath:'id'});open.result.createObjectStore('meta',{keyPath:'key'});};db=await req(open);await reload();}catch(e){toast('기기 저장소를 열 수 없습니다. Safari 일반 모드에서 다시 열어주세요.');document.querySelectorAll('button,input').forEach(el=>el.disabled=true);}})();
